"""Durable essay fixture-marking worker with no network or model dependency."""

from __future__ import annotations

import re
import socket
from dataclasses import dataclass

from .english_essay_service import essay_word_count

FIXTURE_VERSION = "english-essay-fixture-v1"
FIXTURE_DISCLAIMER = (
    "This feedback was generated by a deterministic development fixture, not a live "
    "AI marker. It is not an official ASEAN Scholarship score or score prediction."
)


@dataclass(frozen=True)
class DeterministicEssayFixtureMarker:
    """Produce stable structured feedback for lifecycle and UI calibration only."""

    fixture_version: str = FIXTURE_VERSION

    def mark(self, job: dict) -> dict:
        body = str(job["submission_body"]).strip()
        words = essay_word_count(body)
        paragraphs = [part.strip() for part in re.split(r"\n+", body) if part.strip()]
        first_sentence = next(
            (part.strip() for part in re.split(r"(?<=[.!?])\s+", body) if part.strip()),
            body,
        )
        evidence = first_sentence[:220] + ("…" if len(first_sentence) > 220 else "")
        criterion_feedback = []
        for index, criterion in enumerate(job["rubric_criteria"]):
            title = criterion["title"]
            if index == 0:
                observation = f'The response opens with: “{evidence}”'
                works = "The response addresses the prompt through a concrete learning example."
                next_step = "State the main insight explicitly, then connect every example back to it."
            elif index == 1:
                observation = (
                    f"The submitted snapshot contains {len(paragraphs)} paragraph"
                    f"{'s' if len(paragraphs) != 1 else ''}."
                )
                works = "The permanent snapshot has a visible sequence that can be revised deliberately."
                next_step = "Use one clear purpose per paragraph and add transitions between ideas."
            elif index == 2:
                observation = f"The submitted snapshot contains {words} words of development."
                works = "A specific situation gives the response material to explain and reflect on."
                next_step = "Add one precise detail and explain why it proves the central point."
            else:
                observation = f'A sentence available for close editing is: “{evidence}”'
                works = "The response communicates its central experience in complete ideas."
                next_step = "Edit for exact verbs, varied sentence openings and unnecessary repetition."
            criterion_feedback.append(
                {
                    "criterion_key": criterion["criterion_key"],
                    "criterion_title": title,
                    "observed_evidence": observation,
                    "what_works": works,
                    "next_step": next_step,
                }
            )
        return {
            "fixture_version": self.fixture_version,
            "criterion_feedback": criterion_feedback,
            "overall_summary": (
                "Use this structured fixture output to test the feedback workflow. "
                "Revise by preserving the central example, clarifying the controlling insight "
                "and adding precise supporting detail."
            ),
            "strengths": [
                "The response contains a concrete experience that can anchor reflection.",
                "The immutable submission provides specific language for revision practice.",
            ],
            "priorities": [
                "Make the central insight explicit and sustain it across the response.",
                "Develop one example with precise detail and explanation.",
            ],
            "learner_disclaimer": FIXTURE_DISCLAIMER,
        }


def process_essay_marking_job(
    repository,
    job_id: str,
    *,
    marker: DeterministicEssayFixtureMarker | None = None,
    worker_id: str | None = None,
    retry_delay_seconds: int = 5,
) -> bool:
    """Claim and process one durable job; return False when it is not claimable."""

    claimed = repository.claim_marking_job(
        job_id,
        worker_id=worker_id or f"fixture-worker:{socket.gethostname()}",
    )
    if claimed is None:
        return False
    try:
        feedback = (marker or DeterministicEssayFixtureMarker()).mark(claimed)
        repository.complete_marking_job(
            job_id,
            lease_token=claimed["lease_token"],
            feedback=feedback,
        )
    except Exception as exc:  # the durable state must survive any marker failure
        repository.fail_marking_job(
            job_id,
            lease_token=claimed["lease_token"],
            error_code="fixture_marking_failed",
            error_message=f"{type(exc).__name__}: {exc}",
            retry_delay_seconds=retry_delay_seconds,
        )
        return False
    return True
